"""An agent's callers as the harness writes them: generated by the judge model, and one briefed before it phones."""

from dataclasses import dataclass, replace
from functools import partial

from runtime.actor import Actor
from runtime.agents import service as agents
from runtime.calls import service as calls
from runtime.evals.parts import Harness
from runtime.evals.service.briefs import brief_of_agent, brief_persona
from runtime.evals.service.writers import write_personas
from runtime.exceptions import NotFound
from runtime.judging import service as judging


@dataclass(frozen=True, slots=True)
class Generated:
    """The callers written, the evals they cost (one each, none on the org's key), and dollars."""

    personas: list[judging.Persona]
    evals: int
    cost_usd: float


# Written on the model the agent's calls are judged on: one eval a persona written, none on the
# org's own key. Nothing is saved; a person keeps the ones worth keeping.
async def generate_personas(
    parts: Harness, actor: Actor, slug: str, *, n: int, about: str, from_call: str | None, template: str | None
) -> Generated:
    """Callers written for the agent from its prompt, tools, knowledge, a call or a template."""
    scope = actor.scope
    async with parts.sessions.begin() as session:
        read = await brief_of_agent(session, parts.describers, parts.store, parts.prompts, scope, slug)
        declaration = await agents.declaration_of(session, scope, slug)
        said = ""
        if from_call is not None:
            call = await calls.read_for_key(session, actor, from_call)
            said = judging.conversation_of(judging.transcript_of(call.entries, call.declaration))
    like = None
    if template is not None:
        found = judging.library_personas().get(template)
        if found is None:
            raise NotFound(f"no persona called {template} in Pinecall's library to write callers for {slug} from")
        like = found.persona
    brief = replace(read, about=about, call=said, template=like)
    run = judging.JudgeRun("generate", "personas", scope.env, evals=n, calls=(from_call,) if from_call else ())
    ask = partial(write_personas, brief=brief, n=n)
    written, spent = await judging.ask_judge_model(
        parts.sessions, parts.vault, scope, declaration, run, ask, parts.logs.agent(slug), count=len
    )
    return Generated(written, spent.evals, spent.judge_cost_usd or 0.0)


# What `pinecall simulate` plays is improvised on its side: it asks here, once, for the caller as the
# gateway would brief it: a library caller given what it phones this agent about; any other as it is.
async def brief_for(parts: Harness, actor: Actor, slug: str, name: str) -> judging.Persona:
    """The persona as a simulation plays it: Pinecall's briefed on this agent (one eval), the agent's own as written."""
    scope = actor.scope
    async with parts.sessions.begin() as session:
        declaration = await agents.declaration_of(session, scope, slug)
        class_personas = None if declaration is None else declaration.personas
        persona = await judging.get_persona(session, actor.org, slug, name, class_personas)
    return await brief_persona(
        parts.sessions, parts.vault, parts.describers, parts.store, parts.prompts, parts.logs, scope, slug, persona
    )
